• Filtrieren
• Eindampfen
• Papierchromatographie (mit Wasser als Laufmittel)',
    content = content
      || jsonb_build_object('originaltext', 'Experimentieren (MB, BO): Trennen von Stoffgemischen:
• Sortieren
• Sedimentieren
• Dekantieren
• Filtrieren
• Eindampfen
• Papierchromatographie (mit Wasser als Laufmittel)')
      || jsonb_build_object('kurzbezeichnung', 'Stoffgemische experimentell trennen (6 Verfahren)')
WHERE id = '10cc8691-99e6-516d-832f-061141793176'::uuid;

-- [99f77e60]: new row 1 of 2 -- Bau eines Samens (confirmed missing, no
-- existing row covers Samenschale/Keimling/Speicherstoffe as its own topic).
INSERT INTO lpm_data_objects (id, object_type, title, description, grade_band, subject_area, content, schema_version, status, submitted_by, project_id, branch_id, standards_document_id, curriculum_sequence)
VALUES (
  '9367ea78-b1e3-4b55-a099-e7bb3bb864ce'::uuid, 'performance_indicator', 'Bau eines Samens beschreiben', 'den Bau eines Samens (Samenschale, Keimling) beschreiben und die Bedeutung der Speicherstoffe Stärke und Fett erläutern',
  '5/6', 'Biologie', '{"id":"MNT-56-M2-FOR-3b","thema":"2.2.7 Samenpflanzen","anmerkung":"Schliesst die Lücke zwischen Fruchtbildung (FOR-3) und Keimungsbedingungen (FOR-4); praktisch gut mit dem Stärke-/Fettnachweis (MNT-56-M2-FOR-3a) kombinierbar","_source_id":"MNT-56-M2-FOR-3b","unterthema":"Fortpflanzung und Entwicklung der Samenpflanzen","_source_file":"lernziele_MNT56.json","alltagsnaehe":"hoch","originaltext":"den Bau eines Samens (Samenschale, Keimling) beschreiben und die Bedeutung der Speicherstoffe Stärke und Fett erläutern","bk_prinzipien":[],"ist_praktisch":false,"kognitionsverb":"beschreiben_erläutern","kurzbezeichnung":"Bau eines Samens beschreiben","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"basiskonzept_id":"bk_struktur_funktion","begruendung":"Die Samenschale schützt den Keimling vor Austrocknung und mechanischer Beschädigung, während die eingelagerten Speicherstoffe (Stärke, Fett) als Bau- und Energiereserve für den Start der Keimung dienen -- ein unmittelbarer Struktur-Funktion-Zusammenhang, der am realen Samen (z. B. aufgeschnittene Bohne) direkt beobachtbar ist.","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Bau und Funktion von Organen"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_stoff_energie_umwandlung","begruendung":"Stärke und Fett sind im Samen angelegte Stoffreserven, die beim späteren Keimen in für das Wachstum des Keimlings nutzbare Energie und Bausubstanz umgewandelt werden -- der Samen ist insofern ein stofflich-energetisches Depot.","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Stoffumwandlung"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_individuelle_entwicklung","begruendung":"Der Samen ist ein Ruhestadium zwischen der Entwicklung in der Mutterpflanze und dem eigenständigen Wachstum des Keimlings -- seine Beschreibung bereitet unmittelbar das nächste Lernziel (Keimung/Wachstum) vor.","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Reproduktion"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_evolutive_entwicklung","begruendung":"Die Investition der Mutterpflanze in Speicherstoffe erhöht die Ueberlebenschance des Keimlings unter widrigen Bedingungen -- ein knapper evolutionärer Hinweis ist möglich, steht aber auf dieser Klassenstufe nicht im Vordergrund.","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":["Fitness"],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_steuerung_regelung","begruendung":"Eine Steuerung/Regelung wird beim reinen Bau-Lernziel nicht thematisiert, erst bei den nachfolgenden Keimungsbedingungen.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_information_kommunikation","begruendung":"Informationsverarbeitung ist für den reinen Samenbau nicht der fachliche Schwerpunkt.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]}],"unterthema_origin":"curriculum","empfohlenes_quartal":"Q1","systemebene_primaer":"Organ","kognitive_anforderung":"reproduktion_und_verstaendnis","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Naturobjekt untersuchen","beschreibung":"Einen gequollenen Bohnensamen aufschneiden und Samenschale, Keimblätter und Keimling direkt beschriften."},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Den Samenbau als beschriftetes Schema zeichnen und mit dem realen Objekt vergleichen."},{"rang":3,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Vorbereitung auf den Stärke-/Fettnachweis: Hypothesen aufstellen, wo im Samen die Reservestoffe sitzen könnten."}],"bezug_zum_lehrplan_kontext":"Schliesst zwischen Fruchtbildung (FOR-3) und Keimungsbedingungen (FOR-4) und bereitet den Stärke-/Fettnachweis praktisch vor.","moegliche_fehlvorstellungen":"Der Samen wird oft als leblos missverstanden, nicht als ruhender, aber lebender Keimling mit Reservestoffen.","evolutionsdidaktischer_impuls":null},"basiskonzepte_primaer":["bk_struktur_funktion"],"empfohlene_klassenstufe":"5","interleaving_empfehlung":[],"ermoeglichende_lernziele":["MNT-56-M2-FOR-4"],"voraussetzende_lernziele":["MNT-56-M2-FOR-3"],"basiskonzepte_sekundaer":["bk_stoff_energie_umwandlung"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb, 'evomentor_de_lernziel_v1.2',
  'accepted', NULL, '1b121ef2-96c2-43f7-aa2b-0e07b8de114a'::uuid, '02cda23b-ab75-4538-9b43-a408ba86127a'::uuid, NULL, 16.7
)
ON CONFLICT (id) DO NOTHING;

-- [99f77e60]: new row 2 of 2 -- Entwicklung einer Pflanze aus dem Samen.
INSERT INTO lpm_data_objects (id, object_type, title, description, grade_band, subject_area, content, schema_version, status, submitted_by, project_id, branch_id, standards_document_id, curriculum_sequence)
VALUES (
  'dee17647-ac27-46d1-a90f-ca2ab63aaf72'::uuid, 'performance_indicator', 'Entwicklung einer Pflanze aus dem Samen beschreiben', 'die Entwicklung einer Pflanze aus dem Samen (Quellung, Keimung, Wachstum des Keimlings) beschreiben',
  '5/6', 'Biologie', '{"id":"MNT-56-M2-FOR-4b","thema":"2.2.7 Samenpflanzen","anmerkung":"Baut direkt auf den Keimungs- und Wachstumsbedingungen (FOR-4) auf -- dort die Bedingungen, hier der tatsächliche Entwicklungsablauf","_source_id":"MNT-56-M2-FOR-4b","unterthema":"Fortpflanzung und Entwicklung der Samenpflanzen","_source_file":"lernziele_MNT56.json","alltagsnaehe":"hoch","originaltext":"die Entwicklung einer Pflanze aus dem Samen (Quellung, Keimung, Wachstum des Keimlings) beschreiben","bk_prinzipien":["Reproduktion und Individualentwicklung"],"ist_praktisch":false,"kognitionsverb":"beschreiben","kurzbezeichnung":"Entwicklung einer Pflanze aus dem Samen beschreiben","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"basiskonzept_id":"bk_individuelle_entwicklung","begruendung":"Quellung, Keimung und das anschliessende Wachstum des Keimlings zur jungen Pflanze sind ein klassischer, gut beobachtbarer individueller Entwicklungsablauf -- vom ruhenden Samen zum eigenständigen Organismus.","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Wachstum und Entwicklung"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_stoff_energie_umwandlung","begruendung":"Während der Keimung werden die im Samen gespeicherten Stärke- und Fettreserven abgebaut und in die für Zellteilung und Wachstum des Keimlings benötigte Energie und Bausubstanz umgewandelt.","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Stoffumwandlung"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_struktur_funktion","begruendung":"Beim Wachstum des Keimlings differenzieren sich Wurzel und Spross aus dem Embryo -- ein erster, einfacher Struktur-Funktion-Bezug zwischen Pflanzenorganen und ihrer späteren Aufgabe.","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_evolutive_entwicklung","begruendung":"Der Zeitpunkt und die Geschwindigkeit der Keimung können als Anpassung an Umweltbedingungen gedeutet werden, dies ist auf dieser Klassenstufe aber nicht der fachliche Schwerpunkt.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_steuerung_regelung","begruendung":"Eine hormonelle oder sensorische Steuerung von Keimung und Wachstum wird auf dieser Klassenstufe nicht behandelt.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_information_kommunikation","begruendung":"Informationsverarbeitung ist für die Beschreibung des Entwicklungsablaufs nicht der fachliche Schwerpunkt.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]}],"unterthema_origin":"curriculum","empfohlenes_quartal":"Q1","systemebene_primaer":"Organismus","kognitive_anforderung":"reproduktion_und_verstaendnis","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Einen eigenen Keimversuch (z. B. Bohne im Glas mit feuchtem Papiertuch) über mehrere Tage beobachten, zeichnen und beschriften."},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Die Stationen Quellung, Keimung, Wachstum als Zeitleiste mit Fotos/Zeichnungen des eigenen Keimversuchs darstellen."},{"rang":3,"favorit":false,"methode":"Kooperative Lernformen","beschreibung":"Gruppen vergleichen ihre Keimversuche unter leicht unterschiedlichen Bedingungen (z. B. Licht/Dunkel) und stellen Ergebnisse gegenüber."}],"bezug_zum_lehrplan_kontext":"Baut auf FOR-4 (Keimungs- und Wachstumsbedingungen) auf und macht den dort benannten Bedingungen den tatsächlichen Entwicklungsablauf zuordenbar.","moegliche_fehlvorstellungen":"Keimung wird oft mit dem Beginn des Wachstums gleichgesetzt; die vorausgehende Quellung (Wasseraufnahme ohne bereits sichtbares Wachstum) wird dabei leicht übersehen.","evolutionsdidaktischer_impuls":null},"basiskonzepte_primaer":["bk_individuelle_entwicklung"],"empfohlene_klassenstufe":"5","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["MNT-56-M2-FOR-4","MNT-56-M2-FOR-3b"],"basiskonzepte_sekundaer":["bk_stoff_energie_umwandlung"],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":2}'::jsonb, 'evomentor_de_lernziel_v1.2',
  'accepted', NULL, '1b121ef2-96c2-43f7-aa2b-0e07b8de114a'::uuid, '02cda23b-ab75-4538-9b43-a408ba86127a'::uuid, NULL, 17.5
)
