-- [a0c72af6]: new row 1 of 3 -- Stoffeigenschaften experimentell ermitteln.
INSERT INTO lpm_data_objects (id, object_type, title, description, grade_band, subject_area, content, schema_version, status, submitted_by, project_id, branch_id, standards_document_id, curriculum_sequence)
VALUES (
  'b52009d8-baeb-4e0a-bc43-5e317c0e4ee9'::uuid, 'performance_indicator', 'Stoffeigenschaften experimentell ermitteln', 'Stoffeigenschaften ausgewählter Stoffe ermitteln, z. B. Farbe, Aggregatzustand, Magnetismus, Siedetemperatur',
  '5/6', 'Biologie', '{"id":"MNT-56-M2-AUF-4c","thema":"2.2.3 Körper – Stoffe – Eigenschaften","anmerkung":"Praktische Gegenstücke zum beschreibenden Lernziel AUF-4a (Reinstoffe anhand von Eigenschaften beschreiben)","_source_id":"MNT-56-M2-AUF-4c","unterthema":"Fachpraktische Arbeiten (Stoffe)","_source_file":"lernziele_MNT56.json","alltagsnaehe":"sehr hoch","originaltext":"Stoffeigenschaften ausgewählter Stoffe ermitteln, z. B. Farbe, Aggregatzustand, Magnetismus, Siedetemperatur","bk_prinzipien":[],"ist_praktisch":true,"kognitionsverb":"ermitteln_experimentieren","kurzbezeichnung":"Stoffeigenschaften experimentell ermitteln","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"basiskonzept_id":"bk_struktur_funktion","begruendung":"Das experimentelle Ermitteln von Eigenschaften wie Magnetismus oder Siedetemperatur schult die Denkweise, dass die messbaren Eigenschaften eines Stoffes dessen mögliche Verwendung bestimmen -- eine Analogie zum biologischen Struktur-Funktion-Prinzip, auch wenn der fachliche Gegenstand hier rein physikalisch-chemisch ist.","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_evolutive_entwicklung","begruendung":"Direkter Evolutionsbezug besteht für dieses rein physikalisch-chemische Experimentierlernziel nicht.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_individuelle_entwicklung","begruendung":"Kein individueller Entwicklungsprozess wird hier untersucht.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_steuerung_regelung","begruendung":"Eine Steuerung/Regelung ist bei der Materialprüfung nicht Gegenstand.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_stoff_energie_umwandlung","begruendung":"Die Siedetemperatur-Bestimmung berührt den Phasenübergang flüssig-gasförmig, also einen stofflich-energetischen Vorgang, wenn auch nur am Rand.","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_information_kommunikation","begruendung":"Informationsverarbeitung ist für diese Materialprüfung nicht relevant.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]}],"unterthema_origin":"curriculum","empfohlenes_quartal":"Q1","systemebene_primaer":"Stoff","kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"In Stationen an mehreren Alltagsstoffen (z. B. Eisennagel, Kochsalz, Oel) Farbe, Aggregatzustand, Magnetismus und näherungsweise Siedetemperatur selbst ermitteln und protokollieren."},{"rang":2,"favorit":false,"methode":"Kooperative Lernformen","beschreibung":"Arbeitsteilige Stationenarbeit in Kleingruppen mit anschliessendem Ergebnisvergleich."},{"rang":3,"favorit":false,"methode":"Protokollieren","beschreibung":"Die ermittelten Eigenschaften in einer einfachen Tabelle je Stoff festhalten."}],"bezug_zum_lehrplan_kontext":"Operationalisiert praktisch das beschreibende Lernziel AUF-4a.","moegliche_fehlvorstellungen":"Magnetismus wird häufig fälschlich als allgemeine Eigenschaft aller Metalle angenommen, nicht nur bestimmter (z. B. Eisen, Nickel).","evolutionsdidaktischer_impuls":null},"basiskonzepte_primaer":["bk_struktur_funktion"],"empfohlene_klassenstufe":"5","interleaving_empfehlung":[],"ermoeglichende_lernziele":[],"voraussetzende_lernziele":["MNT-56-M2-AUF-4a"],"basiskonzepte_sekundaer":[],"skalenuebergang_erforderlich":false,"geschaetzte_unterrichtsstunden":1}'::jsonb, 'evomentor_de_lernziel_v1.2',
