  '5/6', 'Biologie', '{"id":"MNT-56-M2-AUF-4d","thema":"2.2.3 Körper – Stoffe – Eigenschaften","anmerkung":"Praktisches Gegenstück zum erklärenden Lernziel AUF-2 (Temperatur und Teilchenbewegung erläutern)","_source_id":"MNT-56-M2-AUF-4d","unterthema":"Fachpraktische Arbeiten (Stoffe)","_source_file":"lernziele_MNT56.json","alltagsnaehe":"sehr hoch","originaltext":"Experimentieren: Veranschaulichen der Teilchenbewegung eines Stoffes (Bewegung von Teilchen in Flüssigkeiten, z. B. offene Tintenpatrone im Wasserglas, Teebeutel in Gefäß mit heißem Wasser)","bk_prinzipien":[],"ist_praktisch":true,"kognitionsverb":"experimentieren_veranschaulichen","kurzbezeichnung":"Teilchenbewegung eines Stoffes veranschaulichen","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"basiskonzept_id":"bk_stoff_energie_umwandlung","begruendung":"Die Diffusion von Farbteilchen im Wasser ist eine direkt beobachtbare Stoffbewegung, und der Vergleich kaltes/heisses Wasser zeigt anschaulich, dass zugeführte thermische Energie die Teilchenbewegung und damit die Ausbreitungsgeschwindigkeit erhöht.","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Stoffumwandlung"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_struktur_funktion","begruendung":"Kein struktureller Organbezug; das Experiment betrifft reine Stoffphysik.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_evolutive_entwicklung","begruendung":"Kein Evolutionsbezug für dieses rein physikalische Diffusionsexperiment.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basis